
/**
 * This is the central entry point for creating queries from various types of input:
 * - If the input is a `Query` instance already, it's returned as-is.
 * - If the input is a `string` or a template literal, it's parsed into a CQN object.
 * - If the input is an `object` with a recognized query kind, it's cast into an instance of
 *   the corresponding query class.
 * @param { Query | string | object } qso - The input, as described above, to be converted into an instance of a Query subclass.
 * @param { ...any } args - Optional arguments for template literals or parameterized queries.
 * @returns { SELECT_ & INSERT_ & UPSERT_ & UPDATE_ & DELETE_ }
 */
export const cql = Query.for = (qso, ...args) => {
  if (!qso || qso instanceof Query) return qso
  if (qso.raw) return cql.cache.query4 (qso, ...args)
  if (typeof qso === 'string') return peg.parse (qso, {args})
  else for (let k in qso) if (k in Query.for) //> usually query.kind is first key
    return Object.setPrototypeOf (qso, Query.for[k].prototype)
  return null //> for any other object
}
export default cql


// Re-export all the helper functions and classes from the xl module
export * from './xl/ttl.js'
import * as peg from '../cql/parser.min.js'
import { Query } from './query.js'
export { Query }

// Export fluent variants of the query classes
import { SELECT as SELECT_ } from './ql/select.js'
import { INSERT as INSERT_ } from './ql/insert.js'
import { UPSERT as UPSERT_ } from './ql/insert.js'
import { UPDATE as UPDATE_ } from './ql/update.js'
import { DELETE as DELETE_ } from './ql/delete.js'
import { CALL as CALL_ } from './ql/call-action.js'

export const SELECT = chimera (SELECT_, SELECT_.columns)
export const INSERT = chimera (INSERT_, INSERT_.entries)
export const UPSERT = chimera (UPSERT_, UPSERT_.entries)
export const UPDATE = chimera (UPDATE_, UPDATE_.entity)
export const DELETE = chimera (DELETE_, DELETE_.from)
export const CALL = chimera (CALL_, CALL_.action)

/**
 * Turns subclasses of Query into fluent APIs that allow constructing instances with `new`
 * as well as plain function calls. For example, this enables usages like these: @example
 * SELECT`ID,title`.from`Books`
 * UPDATE`Books`.with`${data}`
 * @param factory - The function to be called when the fluent API is invoked without `new`.
 * @type <clazz> (clazz:clazz, factory:()=> clazz) => factory & clazz
 */
function chimera (clazz, factory) { const kind = clazz.name
  function fx (...args) { return new.target ? new clazz : factory.call (clazz,...args) }
  Object.defineProperty (clazz.prototype, '_', { get(){ return this[kind] }})
  Object.defineProperty (clazz.prototype, 'kind', { value: kind })
  Object.defineProperty (clazz, 'name', { value: 'Query' })
  Object.defineProperty (fx, 'name', { value: kind })
  Object.defineProperty (fx, 'class', { value: clazz })
  Object.defineProperty (fx, 'prototype', { value: clazz.prototype })
  Object.setPrototypeOf (fx,clazz) //> adds static members
  return Query.for[kind] = fx
}


// Prepare a cache for parsed queries, and export it as part of the cql facade
// for easy access and control over caching behavior.
import { QueryCache } from './ql/cache.js'
cql.cache = new QueryCache
cql.cache.enabled = false //> disable caching by default
